const branch = (n) => Array.isArray(n);
const makeNode = (n, kids) => kids;            // one protocol: arrays, JSON, ASTs

const loc = (node, path) => ({ node, path });  // path = [{ parent, index }, ...]
const down = (l) => (branch(l.node) && l.node.length
  ? loc(l.node[0], [...l.path, { parent: l.node, index: 0 }]) : null);
const up = (l) => {
  const { parent, index } = l.path[l.path.length - 1];
  const kids = parent.slice();                 // copy siblings, keep sharing the rest
  kids[index] = l.node;
  return loc(makeNode(parent, kids), l.path.slice(0, -1));
};

