import { arrayZipper } from "@thi.ng/zipper";

const x = [1, [5, 4, 3, 2], 6];
const edited = arrayZipper(x)        // an immutable location
  .next.next.down.rightmost.left     // navigate to the value 3
  .remove()                          // local edit
  .up.up.appendChild(7)              // another local edit
  .root;                             // zip once: O(depth)
// x is untouched: edited == [1, [5, 4, 2], 6, 7]
